// Implementing queue, using linked list.

class Node<T> {
    var value: T
    var next: Node?
    weak var prev: Node?

    init(_ value: T) {
        self.value = value
    }
}

class Queue<T> {
    private var head: Node<T>?
    private var tail: Node<T>?

    init() {}

    init(array elements: [T]) {
        for element in elements {
            enqueue(element)
        }
    }

    func enqueue(_ item: T) {
        let newNode = Node(item)
        if head == nil {
            head = newNode
            tail = newNode
        } else {
            tail?.next = newNode
            newNode.prev = tail
            tail = newNode
        }
    }

    func dequeue() -> T? {
        if let currentHead = head {
            head = currentHead.next
            head?.prev = nil
            return currentHead.value
        }
        return nil
    }

    func isEmpty() -> Bool {
        return head == nil
    }
}

